//! Conversion candidate types shared between Host, TIP and presentation layers.

use serde::{Deserialize, Serialize};

/// Origin of a conversion candidate item.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CandidateSource {
    /// The currently applied conversion result (always index 0).
    CurrentResult,
    /// Generated by OpenAI or the remote LLM provider.
    Llm,
    /// Generated by Nakaguro (・) delimiter normalization.
    Nakaguro,
    /// Symbol derived from Mozc symbol table (BSD-3-Clause).
    MozcSymbol,
    /// Homophone derived from Sudachi lexicon table (Apache-2.0).
    SudachiHomophone,
}

impl CandidateSource {
    /// Human-readable label for UI display.
    pub fn label(&self) -> &'static str {
        match self {
            Self::CurrentResult => "現在",
            Self::Llm => "AI",
            Self::Nakaguro => "中黒",
            Self::MozcSymbol => "記号",
            Self::SudachiHomophone => "辞書",
        }
    }
}

/// A structured candidate item ready for presentation and selection.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct CandidateItem {
    pub text: String,
    pub source: CandidateSource,
    pub annotation: Option<String>,
}

impl CandidateItem {
    pub fn new(text: impl Into<String>, source: CandidateSource) -> Self {
        Self {
            text: text.into(),
            source,
            annotation: None,
        }
    }

    pub fn with_annotation(
        text: impl Into<String>,
        source: CandidateSource,
        annotation: impl Into<String>,
    ) -> Self {
        Self {
            text: text.into(),
            source,
            annotation: Some(annotation.into()),
        }
    }
}
